      "achados": [
        {
          "proposicao": "A integridade dos sistemas de offloading, incluindo mangote de offloading, marine breakaway couplings, ponto de transferência e hawsers do petroleiro, deve ser baseada em política do operador para inspeção, manutenção, testes, recertificação e retirada de serviço.",
          "trechos": [
            "E543829615f23c3fa:699:1397"
          ],
          "condicoes": [
