      "achados": [
        {
          "proposicao": "O sistema de ancoragem é descrito como responsável por restringir deslocamentos causados por carregamento ambiental e manter a unidade dentro de uma região em que as operações possam ser executadas com segurança.",
          "trechos": [
            "E256ac88faae72067:0:698"
